            </el-table-column>
            <el-table-column label="操作" width="160" fixed="right">
              <template #default="{ row }">
                <el-button link type="primary" @click="openDocument(row)">查看</el-button>
                <el-button link type="primary" @click="downloadDocument(row)">下载</el-button>
                <el-button 
                  v-if="canDelete(row)" 
                  link 
                  type="danger" 
                  @click="handleDelete(row)"
                >删除</el-button>
              </template>
            </el-table-column>
          </el-table>

          <div v-if="documents.length > 0" class="mobile-document-list" v-loading="loading">
            <div
              v-for="row in documents"
              :key="row.id"
              class="mobile-document-card"
            >
              <div class="mobile-doc-top">
                <div class="doc-icon" :style="{ background: getFileIconBg(row.type) }">
                  <el-icon :size="18" :color="getFileIconColor(row.type)">
                    <Document />
                  </el-icon>
                </div>
                <div class="mobile-doc-main">
                  <div class="mobile-doc-title">{{ row.title }}</div>
                  <div class="mobile-doc-desc">{{ row.description || '暂无描述' }}</div>
                </div>
              </div>
              <div class="mobile-doc-meta">
                <span>分类：{{ getTypeText(row.type) }}</span>
                <span>上传者：{{ row.creator_name || '未知' }}</span>
                <span>大小：{{ formatSize(row.file_size) }}</span>
                <span>时间：{{ formatDate(row.created_at) }}</span>
              </div>
              <div class="mobile-doc-actions">
                <el-button size="small" plain @click="openDocument(row)">查看</el-button>
                <el-button size="small" type="primary" plain @click="downloadDocument(row)">下载</el-button>
                <el-button
                  v-if="canDelete(row)"
                  size="small"
                  type="danger"
                  plain
                  @click="handleDelete(row)"
                >
                  删除
                </el-button>
              </div>
            </div>
          </div>
          <div v-if="documents.length === 0" class="empty-state">
            <el-empty description="暂无相关文档" />
          </div>
        </div>
      </div>
    </div>

    <el-dialog v-model="uploadVisible" title="上传新文档" width="520px" class="feishu-dialog">
      <el-form :model="uploadForm" label-position="top">
        <el-form-item label="文档标题" required>
          <el-input v-model="uploadForm.title" placeholder="请输入文档名称" maxlength="100" show-word-limit />
        </el-form-item>
        <el-form-item label="所属分类" required>
          <el-select v-model="uploadForm.type" placeholder="请选择分类" style="width: 100%">
            <el-option label="设备手册" value="equipment_manual" />
            <el-option label="实验报告" value="experiment_report" />
            <el-option label="规章制度" value="policy" />
            <el-option label="其他" value="other" />
          </el-select>
        </el-form-item>
        <el-form-item label="文档描述">
          <el-input v-model="uploadForm.description" type="textarea" :rows="2" placeholder="简单描述一下文档内容..." maxlength="500" show-word-limit />
        </el-form-item>
        <el-form-item label="选择文件" required>
          <div class="upload-area" :class="{ 'has-file': uploadForm.file }">
            <el-upload
              ref="uploadRef"
              class="upload-trigger"
              drag
              action="#"
              :auto-upload="false"
              :show-file-list="false"
              :on-change="handleFileChange"
              :on-remove="handleFileRemove"
              :before-remove="handleBeforeRemove"
              :limit="1"
              :accept="acceptTypes"
            >
              <div v-if="!uploadForm.file" class="upload-placeholder">
                <el-icon class="upload-icon"><upload-filled /></el-icon>
                <div class="upload-text">将文件拖到此处，或<em>点击上传</em></div>
                <div class="upload-hint">支持 PDF、Word、Excel、PPT、图片、文本，单文件不超过 50MB</div>
              </div>
            </el-upload>

            <div v-if="uploadForm.file" class="file-preview">
              <div class="file-info">
                <div class="file-icon-wrap">
                  <el-icon :size="28" :color="getUploadFileIconColor(uploadForm.file.raw?.name)">
                    <component :is="getUploadFileIcon(uploadForm.file.raw?.name)" />
                  </el-icon>
                </div>
                <div class="file-details">
                  <div class="file-name">{{ uploadForm.file.raw?.name }}</div>
                  <div class="file-meta">
                    <span>{{ formatUploadSize(uploadForm.file.raw?.size) }}</span>
                    <el-tag v-if="isImageFile(uploadForm.file.raw?.name)" size="small" type="success">图片</el-tag>
                    <el-tag v-else size="small" type="info">文档</el-tag>
                  </div>
                </div>
              </div>
              <el-button type="danger" plain size="small" @click="handleFileRemove">移除</el-button>
            </div>
          </div>

          <div v-if="uploading" class="upload-progress">
            <el-progress :percentage="uploadProgress" :stroke-width="6" />
