      <template #footer>
        <el-button @click="handleCloseUpload">取消</el-button>
        <el-button type="primary" @click="submitUpload" :loading="submitting" :disabled="!canUpload">
          {{ submitting ? '上传中...' : '开始上传' }}
        </el-button>
      </template>
    </el-dialog>

    <el-dialog v-model="detailVisible" :title="selectedDoc?.title" width="600px" class="feishu-dialog">
      <div v-if="selectedDoc" class="doc-detail">
        <div class="detail-card">
          <div class="detail-row">
            <span class="detail-label">文件名</span>
            <span class="detail-value">{{ selectedDoc.title }}</span>
          </div>
          <div class="detail-row">
            <span class="detail-label">文档类型</span>
            <el-tag size="small" :type="getTypeTagType(selectedDoc.type)">{{ getTypeText(selectedDoc.type) }}</el-tag>
          </div>
          <div class="detail-row">
            <span class="detail-label">上传者</span>
            <span class="detail-value">{{ selectedDoc.creator_name }}</span>
          </div>
