<script setup>
import { ref, onMounted, watch, reactive, computed } from 'vue'
import { FolderOpened, Upload, Search, Document, UploadFilled, Notebook, Files, Guide } from '@element-plus/icons-vue'
import api from '@/api'
import dayjs from 'dayjs'
import { ElMessage, ElMessageBox } from 'element-plus'

const loading = ref(false)
const submitting = ref(false)
const uploading = ref(false)
const uploadProgress = ref(0)
const uploadRef = ref(null)
const documents = ref([])
const typeFilter = ref('')
const searchKeyword = ref('')
const uploadVisible = ref(false)
const detailVisible = ref(false)
const selectedDoc = ref(null)
const currentUser = ref(null)

const categories = [
  { label: '全部文档', value: '', icon: 'FolderOpened' },
  { label: '设备手册', value: 'equipment_manual', icon: 'Notebook' },
  { label: '实验报告', value: 'experiment_report', icon: 'Files' },
  { label: '规章制度', value: 'policy', icon: 'Guide' },
  { label: '其他', value: 'other', icon: 'Document' }
]

const acceptTypes = '.pdf,.doc,.docx,.xls,.xlsx,.ppt,.pptx,.jpg,.jpeg,.png,.gif,.webp,.txt,.zip'
const maxFileSize = 50 * 1024 * 1024

const uploadForm = reactive({
  title: '',
  type: 'other',
  description: '',
  file: null
})

const canUpload = computed(() => {
  return uploadForm.title.trim() && uploadForm.type && uploadForm.file && !submitting.value
})

const fetchDocuments = async () => {
  loading.value = true
  try {
    const params = {}
    if (typeFilter.value) params.type = typeFilter.value
    if (searchKeyword.value) params.search = searchKeyword.value
    const res = await api.getDocuments(params)
    documents.value = res.data.results || res.data || []
  } catch (error) {
    ElMessage.error('获取文档失败')
  } finally {
    loading.value = false
  }
}

watch([typeFilter], () => {
  fetchDocuments()
})

const openUploadDialog = () => {
  Object.assign(uploadForm, { title: '', type: 'other', description: '', file: null })
  uploadProgress.value = 0
  uploading.value = false
  uploadVisible.value = true
}

const handleFileChange = (file) => {
  if (file.raw && file.raw.size > maxFileSize) {
    ElMessage.warning(`文件大小不能超过 ${maxFileSize / (1024 * 1024)} MB`)
    return
  }
  uploadForm.file = file
  if (!uploadForm.title) {
    const ext = file.name.split('.').pop()
    uploadForm.title = file.name.replace(new RegExp(`\.${ext}$`, 'i'), '')
  }
}

const handleFileRemove = () => {
  uploadForm.file = null
}

const handleBeforeRemove = (file) => {
  return ElMessageBox.confirm(`确定移除 ${file.name} 吗？`, '提示', {
    confirmButtonText: '确定',
    cancelButtonText: '取消',
    type: 'warning'
  }).then(() => true).catch(() => false)
}

const submitUpload = async () => {
  if (!uploadForm.title.trim()) {
    ElMessage.warning('请填写文档标题')
    return
  }
  if (!uploadForm.file) {
    ElMessage.warning('请选择要上传的文件')
    return
  }
  submitting.value = true
  uploading.value = true
  uploadProgress.value = 0
  try {
    const fd = new FormData()
    fd.append('title', uploadForm.title.trim())
    fd.append('type', uploadForm.type)
    fd.append('description', uploadForm.description.trim() || '')
    fd.append('file', uploadForm.file.raw || uploadForm.file)
    const res = await api.createDocument(fd)
    ElMessage.success('文档上传成功')
    uploadVisible.value = false
    Object.assign(uploadForm, { title: '', type: 'other', description: '', file: null })
    fetchDocuments()
  } catch (error) {
    const status = error?.response?.status
    const message = status === 413
      ? '文件过大，服务器最多支持 50MB'
      : api.getErrorMessage(error, '上传失败，请重试')
    ElMessage.error(message)
  } finally {
    submitting.value = false
    uploading.value = false
    uploadProgress.value = 0
  }
}

const handleCloseUpload = () => {
  if (submitting.value) {
    ElMessage.warning('上传中，请稍候...')
    return
  }
  uploadVisible.value = false
}

const viewDocument = (doc) => {
  selectedDoc.value = doc
  detailVisible.value = true
}

const openDocument = (doc) => {
  const base = api.getBackendBaseURL()
  const url = doc.file || doc.file_path
  if (!url) {
    ElMessage.error('该文档没有可访问的文件')
    return
  }
  const viewUrl = `${base}/api/core/documents/download/?path=${encodeURIComponent(url)}`
  window.open(viewUrl, '_blank')
}

const downloadDocument = (doc) => {
  const base = api.getBackendBaseURL()
  const url = doc.file || doc.file_path
  if (!url) {
    ElMessage.error('该文档没有可下载的文件')
    return
  }
  const downloadUrl = `${base}/api/core/documents/download/?path=${encodeURIComponent(url)}`
  window.open(downloadUrl, '_blank')
}

const handleDelete = (doc) => {
  ElMessageBox.confirm(`确定要删除文档【${doc.title}】吗？`, '警告', {
    confirmButtonText: '确定删除',
    cancelButtonText: '取消',
    type: 'warning'
  }).then(async () => {
    try {
      await api.deleteDocument(doc.id)
      ElMessage.success('删除成功')
      fetchDocuments()
    } catch (error) {
      ElMessage.error(api.getErrorMessage(error, '删除失败'))
    }
  }).catch(() => {})
}

const canDelete = (doc) => {
  return currentUser.value?.role === '管理员' || doc.creator === currentUser.value?.user_id
}

const formatSize = (bytes) => {
  if (!bytes || bytes === 0) return '0 B'
  const k = 1024
  const sizes = ['B', 'KB', 'MB', 'GB']
  const i = Math.floor(Math.log(bytes) / Math.log(k))
  return parseFloat((bytes / Math.pow(k, i)).toFixed(2)) + ' ' + sizes[i]
}

const formatDate = (date) => dayjs(date).format('YYYY-MM-DD HH:mm')
const getTypeText = (type) => {
  const cat = categories.find(c => c.value === type)
  return cat ? cat.label : type
}
const getTypeTagType = (type) => {
  const map = { equipment_manual: '', experiment_report: 'success', policy: 'warning', other: 'info' }
  return map[type] || 'info'
}
const getFileIconColor = (type) => {
  const colors = { equipment_manual: '#3370ff', experiment_report: '#00b42a', policy: '#ff7d00', other: '#909399' }
  return colors[type] || '#909399'
}
const getFileIconBg = (type) => {
  const colors = { equipment_manual: 'rgba(51,112,255,0.1)', experiment_report: 'rgba(0,180,42,0.1)', policy: 'rgba(255,125,0,0.1)', other: 'rgba(144,147,153,0.1)' }
  return colors[type] || 'rgba(144,147,153,0.1)'
}
const formatUploadSize = (bytes) => {
  if (!bytes || bytes === 0) return '0 B'
  return formatSize(bytes)
}
const isImageFile = (filename) => {
  if (!filename) return false
  return /\.(jpg|jpeg|png|gif|webp)$/i.test(filename)
}
const getUploadFileIcon = (filename) => {
  if (!filename) return Document
  const ext = filename.split('.').pop()?.toLowerCase()
  const iconMap = {
    pdf: 'Document', doc: 'Document', docx: 'Document',
    xls: 'Files', xlsx: 'Files',
    ppt: 'Notebook', pptx: 'Notebook',
    jpg: 'Picture', jpeg: 'Picture', png: 'Picture', gif: 'Picture', webp: 'Picture',
    txt: 'Document', zip: 'FolderOpened'
  }
  return iconMap[ext] || 'Document'
}
const getUploadFileIconColor = (filename) => {
  if (!filename) return '#909399'
  const ext = filename.split('.').pop()?.toLowerCase()
  const colorMap = {
    pdf: '#ff7d00', doc: '#3370ff', docx: '#3370ff',
    xls: '#00b42a', xlsx: '#00b42a',
    ppt: '#f53f3f', pptx: '#f53f3f',
    jpg: '#909399', jpeg: '#909399', png: '#909399', gif: '#909399', webp: '#909399',
    txt: '#909399', zip: '#ff7d00'
  }
  return colorMap[ext] || '#909399'
}

onMounted(() => {
  const userStr = localStorage.getItem('user')
  if (userStr) currentUser.value = JSON.parse(userStr)
  fetchDocuments()
})
</script>

